insert into public.recipes (slug, name, description, meal_types, servings, prep_minutes, difficulty, equipment, instructions, cooked_yield_g, reliability, source_name, source_url, is_demo) values ('jajecznica-z-papryka', 'Jajecznica z papryką i chlebem żytnim', 'Jajecznica na oleju z papryką i cebulą, podana z pieczywem.', array['breakfast', 'dinner']::text[], 1, 10, 'easy', array['stove']::text[], array['Na rozgrzanym oleju podsmaż cebulę i paprykę przez 3 minuty.', 'Wbij jaja i smaż, delikatnie mieszając, do ścięcia.', 'Podawaj z chlebem.']::text[], null, 'unverified', 'Przepis przykładowy (demo) — nieprzetestowany, masa po przygotowaniu szacunkowa', null, true);
