insert into public.recipes (slug, name, description, meal_types, servings, prep_minutes, difficulty, equipment, instructions, cooked_yield_g, reliability, source_name, source_url, is_demo) values ('kurczak-curry-z-ryzem', 'Kurczak curry z papryką i ryżem', 'Obiad na dwie porcje — kurczak duszony z warzywami i przyprawą curry.', array['lunch', 'dinner']::text[], 2, 30, 'easy', array['stove']::text[], array['Ugotuj ryż zgodnie z instrukcją na opakowaniu.', 'Na oleju podsmaż cebulę, dodaj kurczaka i smaż 5–6 minut.', 'Dodaj paprykę i curry, podlej odrobiną wody i duś 10 minut.', 'Podawaj z ryżem.']::text[], 900, 'unverified', 'Przepis przykładowy (demo) — nieprzetestowany, masa po przygotowaniu szacunkowa', null, true);
